bool nativeLayoutFits(){RECT client;GetClientRect(window,&client);std::vector<RECT> bounds;for(HWND h=GetWindow(window,GW_CHILD);h;h=GetWindow(h,GW_HWNDNEXT)){RECT r;GetWindowRect(h,&r);MapWindowPoints(nullptr,window,(POINT*)&r,2);if(r.left<0||r.top<0||r.right>client.right||r.bottom>client.bottom)return false;for(auto& previous:bounds){RECT overlap;if(IntersectRect(&overlap,&r,&previous))return false;}bounds.push_back(r);}return true;}
bool nativePreview(){RECT r;GetClientRect(window,&r);HDC screen=GetDC(window),dc=CreateCompatibleDC(screen);HBITMAP bitmap=CreateCompatibleBitmap(screen,r.right,r.bottom);auto previous=SelectObject(dc,bitmap);SendMessageW(window,WM_PRINT,(WPARAM)dc,PRF_CLIENT|PRF_CHILDREN|PRF_ERASEBKGND);SelectObject(dc,previous);BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=r.right;info.bmiHeader.biHeight=-r.bottom;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;std::vector<char> pixels((size_t)r.right*r.bottom*4);bool ok=GetDIBits(dc,bitmap,0,r.bottom,pixels.data(),&info,DIB_RGB_COLORS)!=0;if(ok){BITMAPFILEHEADER header{};header.bfType=0x4d42;header.bfOffBits=sizeof(header)+sizeof(info.bmiHeader);header.bfSize=header.bfOffBits+(DWORD)pixels.size();std::ofstream file("native-preview.bmp",std::ios::binary);file.write((char*)&header,sizeof(header));file.write((char*)&info.bmiHeader,sizeof(info.bmiHeader));file.write(pixels.data(),pixels.size());ok=bool(file);}DeleteObject(bitmap);DeleteDC(dc);ReleaseDC(window,screen);return ok;}
