int nativeLiveTests(){std::ofstream report("native-live-test.txt");int failures=0;auto check=[&](bool ok,const char* name){report<<(ok?"PASS ":"FAIL ")<<name<<'\n';if(!ok)++failures;};try{auto r=run({L"search",L"--id",L"Microsoft.PowerToys",L"--exact",L"--source",L"winget",L"--accept-source-agreements",L"--disable-interactivity"},120);auto found=parse(r.output);check(r.code==0&&!found.empty()&&found[0].id==L"Microsoft.PowerToys","live exact remote search");r=run({L"list",L"--accept-source-agreements",L"--disable-interactivity"},120);check(listSuccess(r)&&!parse(r.output).empty(),"live installed packages");r=run({L"list",L"--upgrade-available",L"--accept-source-agreements",L"--disable-interactivity"},120);check(listSuccess(r),"live updates listing");r=run({L"search",L"--query",L"wingetswift-test-no-match-918273",L"--source",L"winget",L"--accept-source-agreements",L"--disable-interactivity"},120);check(listSuccess(r)&&parse(r.output).empty(),"live no-match search");auto path=fs::temp_directory_path()/(L"WingetSwift-native-export-"+wnumber(GetCurrentProcessId())+L".json");r=run({L"export",L"--output",path.wstring(),L"--include-versions",L"--accept-source-agreements",L"--disable-interactivity"},120);std::ifstream file(path);std::string json((std::istreambuf_iterator<char>(file)),{});file.close();check(r.code==0&&json.find("PackageIdentifier")!=json.npos,"live migration export");fs::remove(path);}catch(const std::exception& e){report<<e.what()<<'\n';++failures;}return failures;}
